#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int minOperationsII(std::vector<int>& nums, int k) {
        if (k < 2) return 0;
        std::vector<int> costEven(k, 0), costOdd(k, 0);
        for (int i = 0; i < (int)nums.size(); ++i) {
            int rem = nums[i] % k;
            for (int r = 0; r < k; ++r) {
                int c = std::min((rem - r + k) % k, (r - rem + k) % k);
                if (i % 2 == 0) costEven[r] += c;
                else costOdd[r] += c;
            }
        }
        std::vector<int> evenIdx(k), oddIdx(k);
        std::iota(evenIdx.begin(), evenIdx.end(), 0);
        std::iota(oddIdx.begin(), oddIdx.end(), 0);
        std::sort(evenIdx.begin(), evenIdx.end(), [&](int a, int b) { return costEven[a] < costEven[b]; });
        std::sort(oddIdx.begin(), oddIdx.end(), [&](int a, int b) { return costOdd[a] < costOdd[b]; });
        int ans = 1e9;
        for (int i = 0; i < std::min(k, 2); ++i) {
            for (int j = 0; j < std::min(k, 2); ++j) {
                int x = evenIdx[i], y = oddIdx[j];
                if (x != y) ans = std::min(ans, costEven[x] + costOdd[y]);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minOperationsII(int[] nums, int k) {
        if (k < 2) return 0;
        int[] costEven = new int[k];
        int[] costOdd = new int[k];
        for (int i = 0; i < nums.length; i++) {
            int rem = nums[i] % k;
            for (int r = 0; r < k; r++) {
                int c = Math.min((rem - r + k) % k, (r - rem + k) % k);
                if (i % 2 == 0) costEven[r] += c;
                else costOdd[r] += c;
            }
        }
        Integer[] evenIdx = new Integer[k];
        Integer[] oddIdx = new Integer[k];
        for (int i = 0; i < k; i++) { evenIdx[i] = i; oddIdx[i] = i; }
        Arrays.sort(evenIdx, Comparator.comparingInt(a -> costEven[a]));
        Arrays.sort(oddIdx, Comparator.comparingInt(a -> costOdd[a]));
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < Math.min(k, 2); i++) {
            for (int j = 0; j < Math.min(k, 2); j++) {
                int x = evenIdx[i], y = oddIdx[j];
                if (x != y) ans = Math.min(ans, costEven[x] + costOdd[y]);
            }
        }
        return ans;
    }
}

function minOperationsII(nums, k) {
    if (k < 2) return 0;
    const costEven = new Array(k).fill(0);
    const costOdd = new Array(k).fill(0);
    for (let i = 0; i < nums.length; i++) {
        const rem = nums[i] % k;
        for (let r = 0; r < k; r++) {
            const c = Math.min((rem - r + k) % k, (r - rem + k) % k);
            if (i % 2 === 0) costEven[r] += c;
            else costOdd[r] += c;
        }
    }
    const evenIdx = Array.from({ length: k }, (_, i) => i).sort((a, b) => costEven[a] - costEven[b]);
    const oddIdx = Array.from({ length: k }, (_, i) => i).sort((a, b) => costOdd[a] - costOdd[b]);
    let ans = Infinity;
    for (let i = 0; i < Math.min(k, 2); i++) {
        for (let j = 0; j < Math.min(k, 2); j++) {
            const x = evenIdx[i], y = oddIdx[j];
            if (x !== y) ans = Math.min(ans, costEven[x] + costOdd[y]);
        }
    }
    return ans;
}
